import type { Product } from '@shop/shared';

const STORAGE_KEY = 'node-shop.saved';

function HeartIcon({ filled }: { filled: boolean }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16">
      <path
        d="M8 14s-6-3.5-6-8a3.5 3.5 0 0 1 6-2.4A3.5 3.5 0 0 1 14 6c0 4.5-6 8-6 8z"
        fill={filled ? 'currentColor' : 'none'}
        stroke="currentColor"
      />
    </svg>
  );
}

export function SaveForLaterButton({ product }: { product: Product }) {
  const saved: string[] = JSON.parse(localStorage.getItem(STORAGE_KEY) ?? '[]');
  const isSaved = saved.includes(product.id);

  const toggle = () => {
    const next = isSaved ? saved.filter((id) => id !== product.id) : [...saved, product.id];
    localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
  };

  return (
    <div
      className="save-for-later"
      style={{ color: isSaved ? '#e11d48' : '#9ca3af' }}
      onClick={toggle}
    >
      <HeartIcon filled={isSaved} />
    </div>
  );
}
